// Typed client generated from FastAPI's OpenAPI schema.
// schema.d.ts is GENERATED by `npm run gen:api` (openapi-typescript) - do not hand-edit it.
import createClient, { type Middleware } from "openapi-fetch";
import type { components, paths } from "./schema";

export type Schemas = components["schemas"];

function traceId(): string {
  const b = new Uint8Array(16);
  crypto.getRandomValues(b);
  return Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
}

// One trace id per UI request: the API carries it through the graph, every MCP call and the audit log.
const tracing: Middleware = {
  onRequest({ request }) {
    request.headers.set("x-trace-id", traceId());
    return request;
  },
};

export const api = createClient<paths>({ baseUrl: "", credentials: "include" });
api.use(tracing);

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

export function unwrap<T>(r: { data?: T; error?: unknown; response: Response }): T {
  if (r.error !== undefined || r.data === undefined) {
    const detail = (r.error as { detail?: unknown } | undefined)?.detail;
    const msg = typeof detail === "string" ? detail : Array.isArray(detail) ? "Please check the form fields." : `HTTP ${r.response.status}`;
    throw new ApiError(r.response.status, msg);
  }
  return r.data;
}
